/* Física — 10 itens inéditos por tópico do Edital PRF nº 1/2021 (5 C + 5 E cada). */
(function () {
  var D = 'Física', n = 0;
  function q(topico, tema, gabarito, enunciado, comentario) {
    n++;
    return { id: 'FIS-' + String(n).padStart(3, '0'), disciplina: D, tema: tema, topico: topico,
             gabarito: gabarito, enunciado: enunciado, comentario: comentario };
  }
  var T1 = '1 Cinemática escalar e vetorial';
  var T2 = '2 Movimento circular';
  var T3 = '3 Leis de Newton e aplicações';
  var T4 = '4 Trabalho';
  var T5 = '5 Potência';
  var T6 = '6 Energia cinética, potencial e atrito';
  var T7 = '7 Conservação de energia';
  var T8 = '8 Quantidade de movimento e impulso';
  var T9 = '9 Colisões';
  window.QUESTOES = (window.QUESTOES || []).concat([
    q(T1, 'Cinemática', 'C', 'Um veículo percorreu 180 km de uma rodovia em 2 h 30 min. Sua velocidade média nesse percurso foi de 72 km/h.', 'Correto. O item pede a velocidade média, que é simplesmente o deslocamento dividido pelo tempo gasto: vm = Δs/Δt.\nPasso a passo: primeiro converta o tempo para uma só unidade. 2 h 30 min = 2 h + 0,5 h = 2,5 h (30 minutos são meia hora). Depois divida: vm = 180 km ÷ 2,5 h = 72 km/h.\nDica de prova: cuidado com o erro clássico de escrever 2 h 30 min como "2,3 h". Minutos não são decimais da hora! 30 min = 0,5 h; 15 min = 0,25 h; 45 min = 0,75 h; 6 min = 0,1 h.'),
    q(T1, 'Cinemática', 'E', 'Uma velocidade de 108 km/h corresponde a 25 m/s.', 'Errado. Para passar de km/h para m/s, divide-se por 3,6; para o caminho inverso, multiplica-se por 3,6.\nPor que 3,6? Porque 1 km/h = 1.000 m / 3.600 s = 1/3,6 m/s.\nResolução: 108 ÷ 3,6 = 30 m/s, e não 25 m/s. Note que 25 m/s corresponderia a 25 × 3,6 = 90 km/h.\nDica de prova: memorize alguns pares que aparecem sempre: 36 km/h = 10 m/s; 54 km/h = 15 m/s; 72 km/h = 20 m/s; 90 km/h = 25 m/s; 108 km/h = 30 m/s.'),
    q(T1, 'Cinemática', 'C', 'Um carro parte do repouso com aceleração constante de 2 m/s². Após 10 s, ele terá percorrido 100 m.', 'Correto. Estamos no movimento uniformemente variado (MUV), em que a aceleração é constante. A função horária do espaço é s = s₀ + v₀t + at²/2.\nComo o carro parte do repouso, v₀ = 0, e tomando s₀ = 0 fica: s = at²/2.\nResolução: s = 2 · 10² / 2 = 2 · 100 / 2 = 100 m. De bônus, a velocidade final é v = v₀ + at = 0 + 2 · 10 = 20 m/s.\nConferência rápida: no MUV, a velocidade média é a média entre a inicial e a final, (0 + 20)/2 = 10 m/s; em 10 s, isso dá 100 m. As duas contas batem.'),
    q(T1, 'Cinemática', 'E', 'Um veículo a 20 m/s freia com desaceleração constante de 5 m/s² até parar. A distância percorrida durante a frenagem é de 80 m.', 'Errado. Quando o problema não informa o tempo, a ferramenta ideal é a equação de Torricelli: v² = v₀² + 2aΔs.\nNa frenagem, a aceleração é contrária ao movimento, então a = −5 m/s², e a velocidade final é zero (o veículo para).\nResolução: 0² = 20² + 2 · (−5) · d ⇒ 0 = 400 − 10d ⇒ d = 40 m. O item afirma 80 m, o dobro do valor correto.\nDica de prova: a distância de frenagem é d = v₀²/(2a). Repare que ela depende do QUADRADO da velocidade: dobrar a velocidade quadruplica a distância de parada. Esse é um dos argumentos físicos mais fortes para os limites de velocidade nas rodovias.'),
    q(T1, 'Cinemática', 'C', 'Uma viatura desloca-se 6 km para leste e, em seguida, 8 km para norte. O módulo do seu deslocamento vetorial é de 10 km.', 'Correto. Deslocamento é grandeza vetorial: só importam o ponto de partida e o de chegada, e não o caminho percorrido.\nOs dois trechos (6 km para leste e 8 km para norte) são perpendiculares, formando os catetos de um triângulo retângulo. O deslocamento resultante é a hipotenusa.\nResolução pelo Teorema de Pitágoras: |d| = √(6² + 8²) = √(36 + 64) = √100 = 10 km.\nDica de prova: o triângulo 3-4-5 (e seus múltiplos, como 6-8-10 e 9-12-15) aparece com enorme frequência. Ao ver catetos proporcionais a 3 e 4, a hipotenusa é proporcional a 5.'),
    q(T1, 'Cinemática', 'E', 'Uma viatura desloca-se 6 km para leste e, em seguida, 8 km para norte. O módulo do seu deslocamento vetorial é de 14 km.', 'Errado. O item confunde dois conceitos diferentes: distância percorrida e deslocamento.\nDistância percorrida é escalar: soma-se tudo o que o veículo andou, 6 + 8 = 14 km.\nDeslocamento é vetorial: liga o ponto inicial ao final em linha reta. Como os trechos são perpendiculares, usamos Pitágoras: √(6² + 8²) = √100 = 10 km.\nDica de prova: o módulo do deslocamento só é igual à distância percorrida quando o movimento é retilíneo e sem inversão de sentido. Em qualquer outro caso, o deslocamento é menor.'),
    q(T1, 'Cinemática', 'C', 'Dois veículos partem simultaneamente, um em direção ao outro, de pontos distantes 300 km, com velocidades constantes de 60 km/h e 90 km/h. Eles se encontrarão após 2 horas.', 'Correto. Quando dois móveis andam em sentidos opostos, um em direção ao outro, a distância entre eles diminui com a soma das velocidades. Essa soma é a velocidade relativa.\nResolução: v_rel = 60 + 90 = 150 km/h. O tempo de encontro é a distância inicial dividida pela velocidade relativa: t = 300 km ÷ 150 km/h = 2 h.\nConferência: em 2 h, o primeiro anda 120 km e o segundo, 180 km; 120 + 180 = 300 km. Fecha certinho.\nDica de prova: sentidos opostos, some as velocidades; mesmo sentido (perseguição), subtraia.'),
    q(T1, 'Cinemática', 'E', 'Em um trecho com fiscalização de velocidade média, um veículo percorreu 10 km em 5 minutos. Sua velocidade média foi de 100 km/h.', 'Errado. É a mesma ideia do radar de velocidade média: divide-se o trecho pelo tempo gasto. O cuidado está nas unidades.\n5 minutos em horas: 5/60 = 1/12 h.\nResolução: vm = 10 km ÷ (1/12) h = 10 · 12 = 120 km/h. O item diz 100 km/h, o que está errado.\nOutra forma de pensar: 10 km em 5 min significa 2 km por minuto; uma hora tem 60 minutos, então 2 · 60 = 120 km/h.\nDica de prova: dividir por uma fração é multiplicar pelo seu inverso. Isso economiza muito tempo na prova.'),
    q(T1, 'Cinemática', 'C', 'Um objeto abandonado de uma altura de 45 m, desprezando-se a resistência do ar e adotando-se g = 10 m/s², atinge o solo após 3 s, com velocidade de 30 m/s.', 'Correto. Trata-se de queda livre: um MUV com v₀ = 0 e aceleração igual a g = 10 m/s².\nTempo de queda: h = gt²/2 ⇒ 45 = 10 · t²/2 ⇒ 45 = 5t² ⇒ t² = 9 ⇒ t = 3 s.\nVelocidade ao chegar: v = g · t = 10 · 3 = 30 m/s. Conferindo por Torricelli: v² = 2gh = 2 · 10 · 45 = 900 ⇒ v = 30 m/s.\nDica de prova: com g = 10 m/s², as distâncias percorridas na queda livre a cada segundo seguem os números ímpares: 5 m, 15 m, 25 m... Somando, 5 + 15 + 25 = 45 m em 3 s.'),
    q(T1, 'Cinemática', 'E', 'Um veículo com velocidade de 10 m/s acelera uniformemente a 2 m/s² ao longo de 24 m. Ao final desse trecho, sua velocidade será de 16 m/s.', 'Errado. Sem informação de tempo, use Torricelli: v² = v₀² + 2aΔs.\nResolução: v² = 10² + 2 · 2 · 24 = 100 + 96 = 196 ⇒ v = √196 = 14 m/s. O item diz 16 m/s.\nRepare na armadilha: 16 m/s seria o resultado de um raciocínio linear incorreto. A velocidade não cresce proporcionalmente à distância; o que cresce linearmente com a distância é o v².\nDica de prova: memorize os quadrados perfeitos até 30² (por exemplo, 14² = 196, 16² = 256). Raízes "bonitas" são um sinal de que a conta está no caminho certo.'),
    q(T2, 'Cinemática', 'C', 'Um veículo percorre uma curva circular de raio 100 m com velocidade de módulo constante igual a 20 m/s. Sua aceleração centrípeta é de 4 m/s².', 'Correto. Em toda curva, mesmo com velocidade escalar constante, existe uma aceleração apontando para o centro: a aceleração centrípeta, a_c = v²/R.\nResolução: a_c = 20² / 100 = 400 / 100 = 4 m/s².\nInterpretação física: é essa aceleração que "puxa" o veículo para dentro da curva e muda continuamente a direção da sua velocidade. Quem fornece a força correspondente, numa pista plana, é o atrito entre pneus e asfalto.'),
    q(T2, 'Cinemática', 'E', 'Uma roda que gira a 120 rpm tem período de rotação de 2 s.', 'Errado. Comece convertendo a frequência para hertz (rotações por segundo): 120 rpm = 120 rotações em 60 s = 2 rotações por segundo = 2 Hz.\nO período é o inverso da frequência: T = 1/f = 1/2 = 0,5 s. Ou seja, a roda dá uma volta a cada meio segundo.\nO item inverteu o raciocínio, tomando 2 (a frequência) como se fosse o período.\nDica de prova: frequência responde "quantas voltas por segundo?"; período responde "quantos segundos por volta?". Um é o inverso do outro.'),
    q(T2, 'Cinemática', 'C', 'Uma roda de raio 0,3 m gira com velocidade angular de 50 rad/s. A velocidade linear de um ponto de sua borda é de 15 m/s.', 'Correto. A relação entre a velocidade linear (a da borda, em m/s) e a velocidade angular (em rad/s) é v = ω · R.\nResolução: v = 50 · 0,3 = 15 m/s.\nInterpretação: todos os pontos da roda giram com o mesmo ω, mas os pontos mais distantes do eixo percorrem círculos maiores e, por isso, têm maior velocidade linear. Atenção: a fórmula só funciona com R em metros e ω em rad/s.'),
    q(T2, 'Cinemática', 'E', 'Se um veículo dobrar sua velocidade ao percorrer a mesma curva circular, sua aceleração centrípeta também dobrará.', 'Errado. A aceleração centrípeta é a_c = v²/R. A velocidade aparece ao quadrado, então a relação não é proporcional.\nSe v passa a 2v: a_c\' = (2v)²/R = 4v²/R = 4 · a_c. A aceleração quadruplica, e não dobra.\nConsequência prática: a força de atrito exigida para fazer a curva também quadruplica. É por isso que entrar em uma curva com o dobro da velocidade é muito mais perigoso do que parece, e é a razão de existirem placas com velocidade máxima específica para curvas.'),
    q(T2, 'Cinemática', 'C', 'Em uma curva plana e horizontal de raio 80 m, com coeficiente de atrito estático entre pneus e pista igual a 0,5 e g = 10 m/s², a velocidade máxima para que o veículo não derrape é de 20 m/s.', 'Correto. Em uma curva plana, quem segura o carro na trajetória é o atrito lateral. A situação-limite (prestes a derrapar) ocorre quando o atrito estático máximo é exatamente a força centrípeta necessária.\nMontagem: μ·N = m·v²/R. Em pista horizontal, N = m·g; logo, μ·m·g = m·v²/R. A massa se cancela!\nResolução: v = √(μ·g·R) = √(0,5 · 10 · 80) = √400 = 20 m/s (72 km/h).\nDica de prova: a velocidade máxima na curva não depende da massa do veículo. Um caminhão e um carro, com o mesmo μ, têm o mesmo limite teórico. Pista molhada reduz μ e, portanto, a velocidade segura.'),
    q(T2, 'Cinemática', 'E', 'No movimento circular uniforme, como o módulo da velocidade é constante, a aceleração do corpo é nula.', 'Errado. Esse é um dos erros conceituais mais cobrados. Velocidade é um vetor, com módulo, direção e sentido.\nNo movimento circular uniforme (MCU), o módulo é constante, mas a direção muda a todo instante, já que o vetor velocidade é sempre tangente à trajetória. Toda mudança no vetor velocidade exige aceleração.\nEssa aceleração é a centrípeta, de módulo v²/R e sempre apontando para o centro da curva. O que é nula no MCU é a aceleração tangencial, aquela que mudaria o módulo da velocidade.\nDica de prova: "uniforme" no MCU refere-se apenas ao módulo da velocidade. Aceleração nula só existe no MRU (movimento retilíneo uniforme).'),
    q(T2, 'Cinemática', 'C', 'Duas polias, de raios 10 cm e 15 cm, estão ligadas por uma correia que não desliza. Se a menor gira a 30 Hz, a maior gira a 20 Hz.', 'Correto. Quando duas polias são ligadas por uma correia que não desliza, todos os pontos da correia têm a mesma velocidade linear. Logo, as bordas das duas polias também têm.\nComo v = 2πfR, igualar as velocidades lineares dá f₁·R₁ = f₂·R₂.\nResolução: 30 · 10 = f₂ · 15 ⇒ f₂ = 300/15 = 20 Hz.\nInterpretação: a polia maior gira mais devagar. Frequência e raio são inversamente proporcionais. É o mesmo princípio das marchas da bicicleta e de transmissões por correia em motores.'),
    q(T2, 'Cinemática', 'E', 'Um corpo em movimento circular com frequência de 5 Hz tem velocidade angular de 5π rad/s.', 'Errado. A velocidade angular se relaciona com a frequência pela fórmula ω = 2π·f, porque cada volta completa corresponde a 2π radianos.\nResolução: ω = 2π · 5 = 10π rad/s. O item esqueceu o fator 2.\nDica de prova: 1 volta = 360° = 2π rad. Sempre que converter voltas (ou hertz) para radianos, multiplique por 2π.'),
    q(T2, 'Cinemática', 'C', 'Para que um carro de 1.000 kg faça uma curva de raio 50 m a 10 m/s, a resultante centrípeta sobre ele deve ser de 2.000 N.', 'Correto. Pela 2ª lei de Newton aplicada ao movimento circular, a resultante que aponta para o centro é F_c = m·a_c = m·v²/R.\nResolução: F_c = 1.000 · 10² / 50 = 1.000 · 100 / 50 = 2.000 N.\nInterpretação: a força centrípeta não é um "novo tipo" de força. É o nome dado à resultante que aponta para o centro. Numa curva plana, quem desempenha esse papel é o atrito entre pneus e pista.'),
    q(T2, 'Cinemática', 'E', 'Um veículo passa pelo topo de uma lombada cujo perfil é um arco circular de raio 40 m. Adotando-se g = 10 m/s², ele perderá contato com a pista a partir de 10 m/s.', 'Errado. No topo de uma lombada convexa, o centro da curva fica abaixo do carro. A resultante centrípeta (para baixo) é o peso menos a normal: P − N = m·v²/R.\nÀ medida que a velocidade aumenta, N diminui. A perda de contato acontece quando N = 0, ou seja, m·g = m·v²/R ⇒ v = √(g·R).\nResolução: v = √(10 · 40) = √400 = 20 m/s, e não 10 m/s. A 10 m/s, o carro ainda está apoiado na pista, com N = m(10 − 100/40) = m · 7,5.\nDica de prova: é por isso que se sente o corpo "leve" ao passar rápido por uma lombada. A normal diminui, e a balança (o banco) "marca menos".'),
    q(T3, 'Dinâmica', 'C', 'Para imprimir aceleração de 2 m/s² a um veículo de 1.200 kg, a força resultante sobre ele deve ser de 2.400 N.', 'Correto. Aplicação direta da 2ª lei de Newton (princípio fundamental da dinâmica): F_R = m · a.\nResolução: F_R = 1.200 · 2 = 2.400 N.\nLembre-se: a força da fórmula é a RESULTANTE, isto é, a soma vetorial de todas as forças (tração do motor menos atritos e resistência do ar, por exemplo). Se houvesse resistências, o motor precisaria fazer força maior que 2.400 N.'),
    q(T3, 'Dinâmica', 'E', 'Segundo a primeira lei de Newton, um corpo em movimento retilíneo uniforme está submetido a uma força resultante não nula.', 'Errado. A 1ª lei de Newton (princípio da inércia) diz exatamente o contrário: se a força resultante é nula, o corpo permanece em repouso ou em movimento retilíneo uniforme (MRU).\nLogo, no MRU a resultante é zero. Isso não significa que não haja forças, e sim que elas se equilibram. Um carro em velocidade constante na estrada tem a força do motor equilibrando atritos e a resistência do ar.\nDica de prova: força não é necessária para manter o movimento, e sim para alterá-lo (acelerar, frear ou mudar a direção). Essa é a grande virada conceitual de Newton em relação a Aristóteles.'),
    q(T3, 'Dinâmica', 'C', 'Um veículo freia em pista horizontal com as rodas travadas. Sendo 0,8 o coeficiente de atrito cinético e g = 10 m/s², a desaceleração é de 8 m/s².', 'Correto. Com as rodas travadas, a única força horizontal é o atrito cinético, que funciona como resultante: F_at = μ·N = μ·m·g.\nPela 2ª lei: μ·m·g = m·a ⇒ a = μ·g (a massa se cancela).\nResolução: a = 0,8 · 10 = 8 m/s².\nObservação prática: a desaceleração não depende da massa do veículo, só do coeficiente de atrito. Por isso os sistemas ABS são importantes: evitam o travamento e mantêm o atrito estático, que é maior que o cinético, além de preservarem a dirigibilidade.'),
    q(T3, 'Dinâmica', 'E', 'As forças de ação e reação têm mesmo módulo e sentidos opostos e, por atuarem sobre o mesmo corpo, anulam-se.', 'Errado. A primeira parte está certa (mesmo módulo, mesma direção, sentidos opostos), mas a conclusão está errada.\nPela 3ª lei de Newton, ação e reação atuam em corpos DIFERENTES. Exemplo: o pneu empurra o chão para trás e o chão empurra o pneu para frente. Uma força está no chão; a outra, no carro.\nForças só podem se anular quando atuam sobre o mesmo corpo. Como o par ação-reação nunca está no mesmo corpo, ele jamais se anula.\nDica de prova: peso e normal de um livro sobre a mesa NÃO são par ação-reação, ambos atuam no livro. A reação do peso é a força com que o livro atrai a Terra.'),
    q(T3, 'Dinâmica', 'C', 'Um bloco de 10 kg desliza por um plano inclinado de 30° sem atrito. Adotando-se g = 10 m/s², sua aceleração é de 5 m/s².', 'Correto. No plano inclinado sem atrito, decompomos o peso em duas componentes: uma perpendicular ao plano (P·cos θ, equilibrada pela normal) e outra paralela ao plano (P·sen θ), que é a resultante.\n2ª lei: m·g·sen θ = m·a ⇒ a = g·sen θ.\nResolução: a = 10 · sen 30° = 10 · 0,5 = 5 m/s². A massa de 10 kg é um dado "distrator": não interfere no resultado.\nDica de prova: memorize sen 30° = 0,5; sen 45° = √2/2 ≈ 0,71; sen 60° = √3/2 ≈ 0,87.'),
    q(T3, 'Dinâmica', 'E', 'Uma pessoa de 70 kg está sobre uma balança dentro de um elevador que acelera para cima a 2 m/s². Adotando-se g = 10 m/s², a força normal sobre a pessoa é de 700 N.', 'Errado. Dentro do elevador acelerando para cima, a pessoa também acelera para cima. Então a normal precisa ser maior que o peso.\n2ª lei (sentido positivo para cima): N − m·g = m·a ⇒ N = m·(g + a).\nResolução: N = 70 · (10 + 2) = 840 N. O valor de 700 N seria a normal com o elevador parado ou em velocidade constante.\nInterpretação: a balança mede a normal, ou seja, o "peso aparente". Subindo e acelerando, você se sente mais pesado; descendo e acelerando, mais leve; em queda livre, a balança marcaria zero.'),
    q(T3, 'Dinâmica', 'C', 'Dois blocos encostados, de 3 kg e 2 kg, sobre uma superfície horizontal sem atrito, são empurrados por uma força horizontal de 20 N aplicada ao bloco de 3 kg. A força que o bloco de 3 kg exerce sobre o de 2 kg é de 8 N.', 'Correto. Os blocos se movem juntos, então primeiro tratamos o conjunto como um só corpo e depois isolamos um deles.\n1) Conjunto: F = (m₁ + m₂)·a ⇒ 20 = 5·a ⇒ a = 4 m/s².\n2) Bloco de 2 kg isolado: a única força horizontal sobre ele é a que o bloco de 3 kg exerce (contato). Logo, f = m₂·a = 2 · 4 = 8 N.\nConferência: no bloco de 3 kg, a resultante é 20 − 8 = 12 N = 3 · 4. Bate.\nDica de prova: a força de contato é sempre a necessária para acelerar o bloco que está "à frente" (o empurrado).'),
    q(T3, 'Dinâmica', 'E', 'Se um objeto de 80 kg fosse levado da Terra para a Lua, sua massa seria reduzida, pois a gravidade lunar é menor.', 'Errado. Massa e peso são grandezas diferentes, e a banca adora confundi-las.\nMassa (kg) é a quantidade de matéria e a medida da inércia do corpo. Não muda de lugar para lugar: 80 kg na Terra, 80 kg na Lua.\nPeso (N) é a força gravitacional, P = m·g. Como g na Lua (≈ 1,6 m/s²) é cerca de 1/6 do terrestre, o peso fica bem menor: ≈ 128 N contra ≈ 800 N na Terra.\nDica de prova: quando alguém diz "peso 80 quilos", está falando de massa. Em Física, peso se mede em newtons.'),
    q(T3, 'Dinâmica', 'C', 'Um carro de 1.000 kg parte do repouso e atinge 20 m/s em 10 s, em movimento uniformemente acelerado. A força resultante sobre ele é de 2.000 N.', 'Correto. São dois passos: primeiro a cinemática (achar a aceleração), depois a dinâmica (achar a força).\n1) a = Δv/Δt = (20 − 0)/10 = 2 m/s².\n2) F_R = m·a = 1.000 · 2 = 2.000 N.\nEsse encadeamento (cinemática ⇒ aceleração ⇒ força) é muito comum em provas. A aceleração é a "ponte" entre o movimento e as forças.'),
    q(T3, 'Dinâmica', 'E', 'Uma caixa de 50 kg está em repouso no piso horizontal de um caminhão parado, com coeficiente de atrito estático 0,4 e g = 10 m/s². Se uma pessoa a empurra horizontalmente com 150 N, a força de atrito sobre a caixa é de 200 N.', 'Errado. Este item testa um ponto sutil: o atrito estático não vale sempre μ·N. O valor μ·N é apenas o MÁXIMO que ele pode atingir.\n1) Atrito estático máximo: F_máx = μ_e·N = 0,4 · (50 · 10) = 0,4 · 500 = 200 N.\n2) A força aplicada (150 N) é menor que 200 N. A caixa não se move.\n3) Se a caixa está em repouso, a resultante é zero; portanto, o atrito é exatamente igual à força aplicada: 150 N.\nDica de prova: o atrito estático "se ajusta" à solicitação, de 0 até μ·N. Só quando a força aplicada supera esse máximo o corpo começa a deslizar.'),
    q(T4, 'Energia e trabalho', 'C', 'Uma força constante de 500 N, paralela ao deslocamento e no mesmo sentido, desloca um veículo por 20 m. O trabalho realizado por essa força é de 10.000 J.', 'Correto. O trabalho de uma força constante é W = F · d · cos θ, em que θ é o ângulo entre a força e o deslocamento.\nForça paralela e no mesmo sentido do deslocamento significa θ = 0° e cos 0° = 1.\nResolução: W = 500 · 20 · 1 = 10.000 J (10 kJ).\nInterpretação: trabalho é a energia transferida pela força. Esses 10.000 J foram transferidos ao veículo.'),
    q(T4, 'Energia e trabalho', 'E', 'Uma força de 100 N, formando ângulo de 60° com o deslocamento, atua ao longo de 10 m. O trabalho realizado é de 1.000 J.', 'Errado. Quando a força forma ângulo com o deslocamento, só a componente paralela ao deslocamento realiza trabalho.\nFórmula: W = F · d · cos θ.\nResolução: W = 100 · 10 · cos 60° = 100 · 10 · 0,5 = 500 J. O item ignorou o cosseno e chegou a 1.000 J.\nDica de prova: cos 0° = 1 (trabalho máximo), cos 60° = 0,5, cos 90° = 0 (trabalho nulo) e cos 180° = −1 (trabalho resistente, negativo).'),
    q(T4, 'Energia e trabalho', 'C', 'Quando um corpo de 20 kg desce verticalmente 5 m, o trabalho realizado pelo seu peso é de +1.000 J, adotando-se g = 10 m/s².', 'Correto. O trabalho do peso depende apenas do desnível vertical: W_P = m·g·h.\nResolução: W_P = 20 · 10 · 5 = 1.000 J.\nO sinal é positivo porque o peso aponta para baixo e o corpo se deslocou para baixo, no mesmo sentido (θ = 0°). Se o corpo subisse 5 m, o trabalho do peso seria −1.000 J.\nDica de prova: o peso é uma força conservativa. Seu trabalho não depende da trajetória (rampa, escada ou queda vertical), apenas das alturas inicial e final.'),
    q(T4, 'Energia e trabalho', 'E', 'Em um deslocamento horizontal de um veículo sobre pista plana, a força normal exercida pela pista realiza trabalho positivo.', 'Errado. A força normal é sempre perpendicular à superfície de apoio. Em pista horizontal, ela é vertical, enquanto o deslocamento é horizontal.\nÂngulo de 90° entre força e deslocamento ⇒ cos 90° = 0 ⇒ W = F·d·0 = 0.\nConclusão: a normal não realiza trabalho nesse deslocamento. Pela mesma razão, o peso também não realiza trabalho em um deslocamento horizontal.\nDica de prova: força perpendicular ao movimento nunca realiza trabalho. Ela pode mudar a direção do movimento, mas não a energia cinética.'),
    q(T4, 'Energia e trabalho', 'C', 'O trabalho da força resultante sobre um carro de 1.000 kg cuja velocidade é reduzida de 20 m/s para 10 m/s é de −150.000 J.', 'Correto. O teorema da energia cinética diz que o trabalho da força RESULTANTE é igual à variação da energia cinética: W_R = Ec_final − Ec_inicial.\nEc_inicial = ½ · 1.000 · 20² = 200.000 J. Ec_final = ½ · 1.000 · 10² = 50.000 J.\nW_R = 50.000 − 200.000 = −150.000 J.\nO sinal negativo indica que a resultante "retirou" energia do carro: é um trabalho resistente (frenagem). Dica: repare que reduzir a velocidade à metade retirou 75% da energia cinética, por causa do v².'),
    q(T4, 'Energia e trabalho', 'E', 'Um bloco de 10 kg desliza 4 m sobre superfície horizontal com coeficiente de atrito cinético 0,5 e g = 10 m/s². O trabalho da força de atrito nesse deslocamento é de +200 J.', 'Errado. O valor numérico até bate, mas o sinal não.\n1) Força de atrito: F_at = μ·N = 0,5 · (10 · 10) = 50 N.\n2) O atrito cinético sempre se opõe ao deslizamento, formando 180° com o deslocamento (cos 180° = −1).\n3) W = 50 · 4 · (−1) = −200 J.\nO trabalho do atrito cinético é negativo: ele transforma energia mecânica em energia térmica (aquecimento das superfícies). O item erra ao afirmar +200 J.'),
    q(T4, 'Energia e trabalho', 'C', 'No movimento circular uniforme, o trabalho da força centrípeta é nulo.', 'Correto. A força centrípeta aponta sempre para o centro da curva, enquanto a velocidade (e o deslocamento instantâneo) é sempre tangente à trajetória. Logo, o ângulo entre elas é 90°.\nW = F·d·cos 90° = 0.\nCoerência com o teorema da energia cinética: no MCU, o módulo da velocidade não muda, então a energia cinética também não muda, e o trabalho da resultante (a centrípeta) tem de ser zero.\nA força centrípeta muda apenas a direção da velocidade, nunca o seu módulo.'),
    q(T4, 'Energia e trabalho', 'E', 'Para elevar com velocidade constante uma carga de 50 kg a uma altura de 3 m, com g = 10 m/s², o trabalho realizado pela força aplicada é de 150 J.', 'Errado. Elevar com velocidade constante significa que a força aplicada é igual ao peso: F = m·g = 50 · 10 = 500 N.\nTrabalho da força aplicada: W = F·h = 500 · 3 = 1.500 J. O item esqueceu de multiplicar por g e chegou a 150 J.\nInterpretação: os 1.500 J correspondem exatamente ao ganho de energia potencial gravitacional da carga (m·g·h).\nDica de prova: peso é m·g. Esquecer o g (ou multiplicar a massa diretamente pela altura) é um erro que a banca explora com frequência.'),
    q(T4, 'Energia e trabalho', 'C', 'Uma força de 40 N atua constante ao longo dos primeiros 5 m de um deslocamento e, nos 5 m seguintes, decresce linearmente até zero. O trabalho total, área sob o gráfico F × d, é de 300 J.', 'Correto. Quando a força varia, calcula-se o trabalho pela ÁREA sob o gráfico F × d. Essa é uma propriedade gráfica muito cobrada.\nDividindo o gráfico em duas figuras:\n1) Retângulo (de 0 a 5 m, F = 40 N): 40 · 5 = 200 J.\n2) Triângulo (de 5 a 10 m, F cai de 40 N a 0): base × altura / 2 = 5 · 40 / 2 = 100 J.\nTotal: 200 + 100 = 300 J.\nDica de prova: área sob F × d dá trabalho; área sob F × t dá impulso; área sob v × t dá deslocamento.'),
    q(T4, 'Energia e trabalho', 'E', 'O trabalho realizado para deformar em 0,1 m uma mola de constante elástica 200 N/m, a partir de seu comprimento natural, é de 20 J.', 'Errado. A força elástica não é constante: cresce conforme a mola deforma (F = k·x, lei de Hooke). Por isso, não se pode usar W = F·d simplesmente.\nO trabalho é a área do triângulo no gráfico F × x: W = k·x²/2.\nResolução: W = 200 · (0,1)² / 2 = 200 · 0,01 / 2 = 1 J. O item afirma 20 J.\nDica de prova: o x está ao quadrado. Com x = 0,1 m, x² = 0,01, e esse detalhe derruba muitos candidatos. Use sempre x em metros.'),
    q(T5, 'Energia e trabalho', 'C', 'Um motor que realiza trabalho de 2.000 J em 4 s desenvolve potência média de 500 W.', 'Correto. Potência média é a rapidez com que o trabalho (energia) é realizado: P = W/Δt.\nResolução: P = 2.000 J ÷ 4 s = 500 W.\nUnidade: 1 watt (W) = 1 joule por segundo (J/s). Ou seja, esse motor transfere 500 J de energia a cada segundo.'),
    q(T5, 'Energia e trabalho', 'E', 'Um caminhão mantém velocidade de 20 m/s com força de tração de 3.000 N. A potência desenvolvida pela tração é de 6 kW.', 'Errado. Para força constante atuando na direção do movimento com velocidade constante, a potência é P = F · v (vem de P = W/t = F·d/t).\nResolução: P = 3.000 N · 20 m/s = 60.000 W = 60 kW. O item afirma 6 kW, errando uma casa decimal.\nDica de prova: atenção aos prefixos. k (quilo) = 10³; M (mega) = 10⁶. 60.000 W = 60 kW = 0,06 MW.'),
    q(T5, 'Energia e trabalho', 'C', 'Um guindaste eleva uma carga de 100 kg a 12 m de altura, com velocidade constante, em 20 s. Com g = 10 m/s², a potência útil é de 600 W.', 'Correto. Potência útil é a energia entregue à carga dividida pelo tempo.\n1) Energia (trabalho) para elevar com velocidade constante: W = m·g·h = 100 · 10 · 12 = 12.000 J.\n2) Potência: P = W/t = 12.000 / 20 = 600 W.\nAlternativa: a velocidade de subida é 12/20 = 0,6 m/s e a força é o peso, 1.000 N; P = F·v = 1.000 · 0,6 = 600 W. Os dois caminhos dão o mesmo resultado.'),
    q(T5, 'Energia e trabalho', 'E', 'Considerando-se 1 cv ≈ 735 W, um motor de 100 cv tem potência de aproximadamente 7,35 kW.', 'Errado. A conversão é direta: 100 cv × 735 W/cv = 73.500 W.\nPassando para quilowatt: 73.500 W ÷ 1.000 = 73,5 kW. O item afirma 7,35 kW, dez vezes menos.\nContexto: o cavalo-vapor (cv) e o horse-power (hp ≈ 746 W) são unidades práticas, fora do SI, muito usadas para motores de veículos.\nDica de prova: faça sempre uma estimativa de ordem de grandeza. 100 cv é um motor de carro popular; 7 kW seria a potência de uma motocicleta pequena.'),
    q(T5, 'Energia e trabalho', 'C', 'Um motor recebe 150 kW de potência e fornece 60 kW de potência útil. Seu rendimento é de 40%.', 'Correto. Rendimento é a fração da potência recebida que é aproveitada: η = P_útil / P_total.\nResolução: η = 60 / 150 = 0,40 = 40%.\nA diferença, 150 − 60 = 90 kW, é a potência dissipada, principalmente na forma de calor (atrito interno, aquecimento, ruído).\nDica de prova: o rendimento é sempre menor que 1 (100%). Motores de combustão interna de automóveis costumam ter rendimento entre 25% e 40%.'),
    q(T5, 'Energia e trabalho', 'E', 'Um equipamento de 2 kW ligado por 3 horas consome 600 Wh de energia.', 'Errado. Energia consumida é potência vezes tempo: E = P · Δt.\nResolução: E = 2 kW · 3 h = 6 kWh. Como 1 kWh = 1.000 Wh, temos 6.000 Wh, dez vezes mais que os 600 Wh do item.\nO kWh (quilowatt-hora) é a unidade de energia usada na conta de luz. Em joules: 1 kWh = 1.000 W · 3.600 s = 3,6 × 10⁶ J.\nDica de prova: kW é potência; kWh é energia. Não confunda.'),
    q(T5, 'Energia e trabalho', 'C', 'Um carro de 1.000 kg acelera do repouso até 30 m/s em 10 s. A potência média associada ao ganho de energia cinética é de 45 kW.', 'Correto. Pelo teorema da energia cinética, o trabalho da resultante é o ganho de energia cinética. A potência média é esse ganho dividido pelo tempo.\n1) ΔEc = ½ · 1.000 · 30² − 0 = 500 · 900 = 450.000 J.\n2) P = 450.000 J / 10 s = 45.000 W = 45 kW.\nObservação: esta é a potência mínima, só para acelerar o carro. Na prática, o motor precisa fornecer mais, para vencer o atrito e a resistência do ar e compensar o próprio rendimento.'),
    q(T5, 'Energia e trabalho', 'E', 'Um veículo trafega a 25 m/s, em velocidade constante, vencendo forças resistivas totais de 2.000 N. A potência do motor transferida às rodas é de 80 kW.', 'Errado. Velocidade constante significa resultante nula (1ª lei de Newton). Então a força de tração é igual às forças resistivas: F_tração = 2.000 N.\nPotência: P = F · v = 2.000 · 25 = 50.000 W = 50 kW. O item afirma 80 kW.\nInterpretação: em velocidade de cruzeiro, toda a potência transferida às rodas é usada apenas para vencer as resistências (atrito de rolamento e arrasto do ar). Como o arrasto cresce com a velocidade, andar mais rápido exige potência muito maior, o que explica o consumo maior de combustível.'),
    q(T5, 'Energia e trabalho', 'C', 'Uma bomba eleva 600 L de água a uma altura de 5 m em 1 minuto. Com densidade da água de 1 kg/L e g = 10 m/s², a potência útil da bomba é de 500 W.', 'Correto. Com densidade de 1 kg/L, 600 L de água correspondem a 600 kg.\n1) Trabalho para elevar: W = m·g·h = 600 · 10 · 5 = 30.000 J.\n2) Tempo: 1 minuto = 60 s.\n3) Potência útil: P = 30.000 / 60 = 500 W.\nDica de prova: em problemas de bomba d\'água, converta volume em massa usando a densidade (água: 1 kg/L ou 1.000 kg/m³) e o tempo para segundos.'),
    q(T5, 'Energia e trabalho', 'E', 'No Sistema Internacional, a unidade watt equivale a joule multiplicado por segundo.', 'Errado. Potência é energia DIVIDIDA pelo tempo, e não multiplicada. Portanto 1 W = 1 J/s (joule por segundo).\n"Joule multiplicado por segundo" (J·s) é outra grandeza: é a unidade de ação, como a da constante de Planck. Nada a ver com potência.\nDica de prova: confira sempre as unidades pela fórmula. P = E/t ⇒ [P] = J/s = W. Analisar unidades é uma ótima forma de detectar itens errados.'),
    q(T6, 'Energia e trabalho', 'C', 'Um automóvel de 1.000 kg a 20 m/s tem energia cinética de 200 kJ.', 'Correto. Energia cinética é a energia associada ao movimento: Ec = m·v²/2.\nResolução: Ec = 1.000 · 20² / 2 = 1.000 · 400 / 2 = 200.000 J = 200 kJ.\nPara dar uma ideia: essa energia equivale à de soltar o mesmo carro de uma altura de 20 m (m·g·h = 1.000 · 10 · 20 = 200 kJ). Em uma colisão a 72 km/h, essa é a energia que precisa ser dissipada.'),
    q(T6, 'Energia e trabalho', 'E', 'Se a velocidade de um veículo triplicar, sua energia cinética também triplicará.', 'Errado. A energia cinética é proporcional ao QUADRADO da velocidade (Ec = m·v²/2).\nSe v vira 3v: Ec\' = m·(3v)²/2 = 9 · m·v²/2 = 9·Ec. A energia fica 9 vezes maior, e não 3.\nImplicação para o trânsito: um carro a 90 km/h tem 9 vezes mais energia que a 30 km/h. Essa energia precisa ser dissipada pelos freios (distância de frenagem 9 vezes maior) ou, numa colisão, pela deformação dos veículos e dos corpos.'),
    q(T6, 'Energia e trabalho', 'C', 'Um corpo de 50 kg a 8 m de altura em relação ao solo tem energia potencial gravitacional de 4.000 J em relação ao solo, adotando-se g = 10 m/s².', 'Correto. A energia potencial gravitacional é a energia "armazenada" pela posição em relação a um nível de referência: Ep = m·g·h.\nResolução: Ep = 50 · 10 · 8 = 4.000 J.\nAtenção: o valor da Ep depende do referencial escolhido. Por isso o item diz "em relação ao solo". Em relação ao topo de um prédio mais alto, por exemplo, a Ep seria negativa.'),
    q(T6, 'Energia e trabalho', 'E', 'Uma mola de constante elástica 400 N/m comprimida em 0,2 m armazena 80 J de energia potencial elástica.', 'Errado. A energia potencial elástica de uma mola deformada é Ep = k·x²/2.\nResolução: Ep = 400 · (0,2)² / 2 = 400 · 0,04 / 2 = 8 J. O item diz 80 J.\nO erro típico é fazer 0,2² = 0,4 em vez de 0,04. Elevar ao quadrado um número menor que 1 o torna AINDA MENOR.\nDica de prova: confira com contas simples. 0,2 = 2/10 ⇒ (2/10)² = 4/100 = 0,04.'),
    q(T6, 'Energia e trabalho', 'C', 'Um veículo a 20 m/s trava as rodas em pista horizontal com coeficiente de atrito cinético 0,5. Adotando-se g = 10 m/s², a distância de frenagem é de 40 m.', 'Correto. Usamos o teorema da energia cinética: o trabalho do atrito retira toda a energia cinética do veículo.\nμ·m·g·d = m·v²/2 ⇒ d = v² / (2·μ·g). A massa se cancela.\nResolução: d = 20² / (2 · 0,5 · 10) = 400 / 10 = 40 m.\nMesmo resultado por Newton + Torricelli: a = μ·g = 5 m/s²; 0 = 400 − 2·5·d ⇒ d = 40 m.\nDica de prova: a distância de frenagem cresce com o quadrado da velocidade e diminui com o coeficiente de atrito. Pista molhada (μ menor) aumenta bastante a distância de parada.'),
    q(T6, 'Energia e trabalho', 'E', 'Dois veículos com a mesma velocidade inicial travam as rodas na mesma pista horizontal, com o mesmo coeficiente de atrito; um deles tem o dobro da massa do outro. O veículo de maior massa percorrerá o dobro da distância até parar.', 'Errado. A intuição engana aqui. Vamos às contas.\nA força de atrito é μ·m·g, proporcional à massa. A desaceleração é a = F/m = μ·g, que não depende da massa.\nDistância de frenagem: d = v²/(2·μ·g). Também não depende da massa.\nO veículo mais pesado tem mais energia cinética, mas também recebe uma força de atrito proporcionalmente maior. Os efeitos se compensam, e ambos param na MESMA distância (no modelo ideal).\nObservação: na vida real, caminhões costumam precisar de distâncias maiores por limitações de freios, aquecimento e distribuição de carga, mas isso foge ao modelo do item.'),
    q(T6, 'Energia e trabalho', 'C', 'Um carro de 800 kg trafega a 25 m/s e freia até parar. A energia dissipada pelas forças de atrito na frenagem é de 250 kJ.', 'Correto. Se o carro freia até parar, toda a sua energia cinética inicial é transformada (dissipada em calor nos freios e nos pneus).\nResolução: Ec = ½ · 800 · 25² = 400 · 625 = 250.000 J = 250 kJ.\nComo a energia final é zero, a energia dissipada é exatamente os 250 kJ iniciais. Essa energia aquece as pastilhas e os discos de freio, o que explica o superaquecimento (fading) em descidas longas.'),
    q(T6, 'Energia e trabalho', 'E', 'Uma força de atrito cinético de 300 N atua sobre um caixote de 60 kg que desliza sobre piso horizontal. Com g = 10 m/s², o coeficiente de atrito cinético é 0,2.', 'Errado. Isole o coeficiente na fórmula do atrito: F_at = μ·N ⇒ μ = F_at / N.\nEm piso horizontal, N = m·g = 60 · 10 = 600 N.\nResolução: μ = 300 / 600 = 0,5. O item diz 0,2.\nDica de prova: o coeficiente de atrito é adimensional (sem unidade) e costuma ficar entre 0 e 1 para a maioria das superfícies comuns. Pneu em asfalto seco fica em torno de 0,7 a 0,9.'),
    q(T6, 'Energia e trabalho', 'C', 'Um caminhão de 1.800 kg com energia cinética de 90 kJ trafega a 10 m/s.', 'Correto. Aqui o caminho é inverso: temos a energia e queremos a velocidade. Isole v em Ec = m·v²/2 ⇒ v = √(2·Ec/m).\nResolução: v = √(2 · 90.000 / 1.800) = √(180.000 / 1.800) = √100 = 10 m/s.\nConferência: Ec = ½ · 1.800 · 10² = 900 · 100 = 90.000 J = 90 kJ. Confere.\nDica de prova: no Cebraspe, muitas vezes é mais rápido testar o valor do item na fórmula do que isolar a incógnita.'),
    q(T6, 'Energia e trabalho', 'E', 'No modelo usual de atrito seco, a força de atrito cinético depende da área de contato entre as superfícies, aumentando com ela.', 'Errado. No modelo usual (leis empíricas de Amontons-Coulomb), a força de atrito vale F_at = μ·N e depende apenas de dois fatores: o coeficiente de atrito (natureza das superfícies) e a força normal.\nA área aparente de contato não aparece na fórmula. Um tijolo deslizando deitado ou em pé sofre o mesmo atrito.\nExplicação intuitiva: com área maior, a pressão (força por área) diminui na mesma proporção. Os contatos microscópicos reais acabam somando praticamente a mesma área efetiva.\nObservação: pneus são um caso especial e mais complexo (deformação, aderência química), mas a prova cobra o modelo básico.'),
    q(T7, 'Energia e trabalho', 'C', 'Desprezando-se a resistência do ar e adotando-se g = 10 m/s², um objeto abandonado de 20 m de altura chega ao solo a 20 m/s.', 'Correto. Sem resistência do ar, a energia mecânica se conserva: a potencial no alto vira cinética no solo.\nm·g·h = m·v²/2 ⇒ v = √(2·g·h). A massa se cancela.\nResolução: v = √(2 · 10 · 20) = √400 = 20 m/s (72 km/h).\nCuriosidade útil: uma colisão a 72 km/h equivale a cair de um prédio de cerca de 7 andares (20 m). Esse tipo de comparação aparece em campanhas de segurança viária.'),
    q(T7, 'Energia e trabalho', 'E', 'Uma bola lançada verticalmente para cima a 30 m/s, sem resistência do ar e com g = 10 m/s², atinge altura máxima de 90 m.', 'Errado. Na subida, a energia cinética vira potencial. No topo, a velocidade é zero.\nm·v₀²/2 = m·g·h ⇒ h = v₀² / (2·g).\nResolução: h = 30² / (2 · 10) = 900 / 20 = 45 m. O item afirma 90 m, provavelmente por esquecer o fator 2 do denominador (900/10).\nConferência pela cinemática: o tempo de subida é 30/10 = 3 s, e a altura é a velocidade média (15 m/s) × 3 s = 45 m.'),
    q(T7, 'Energia e trabalho', 'C', 'Um carrinho parte do repouso a 45 m de altura e desce sem atrito até um ponto a 25 m de altura. Com g = 10 m/s², sua velocidade nesse ponto é de 20 m/s.', 'Correto. Sem atrito, a energia mecânica se conserva. O que importa é o desnível percorrido: Δh = 45 − 25 = 20 m.\nA energia potencial perdida vira cinética: m·g·Δh = m·v²/2 ⇒ v = √(2·g·Δh).\nResolução: v = √(2 · 10 · 20) = √400 = 20 m/s.\nDica de prova: não use as alturas absolutas (45 ou 25 m) isoladamente; use a diferença. A forma da trajetória (rampa curva, reta etc.) não importa sem atrito.'),
    q(T7, 'Energia e trabalho', 'E', 'Um pêndulo simples passa pelo ponto mais baixo da trajetória a 4 m/s. Desprezando-se atritos e adotando-se g = 10 m/s², ele sobe até 1,6 m acima desse ponto.', 'Errado. No ponto mais baixo, a energia é toda cinética; no ponto mais alto, toda potencial (velocidade momentaneamente nula).\nm·v²/2 = m·g·h ⇒ h = v² / (2·g).\nResolução: h = 4² / (2 · 10) = 16 / 20 = 0,8 m. O item diz 1,6 m, o dobro, por esquecer de dividir por 2.\nNote que o comprimento do fio e a massa do pêndulo não interferem: só a velocidade no ponto baixo determina a altura alcançada.'),
    q(T7, 'Energia e trabalho', 'C', 'Um caminhão sem freios entra a 25 m/s em uma rampa de escape. Desprezando-se atritos e adotando-se g = 10 m/s², ele subiria até uma altura de 31,25 m.', 'Correto. Rampas de escape são exatamente uma aplicação da conservação de energia: a energia cinética do caminhão desgovernado é convertida em potencial ao subir.\nh = v² / (2·g) = 25² / 20 = 625 / 20 = 31,25 m.\nNa prática, as rampas reais usam também caixas de brita ou areia, que dissipam energia por atrito e deformação. Assim, o caminhão para com altura e comprimento muito menores do que o cálculo ideal sugere.'),
    q(T7, 'Energia e trabalho', 'E', 'Em um sistema no qual atuam forças de atrito dissipativas, a energia mecânica total se conserva.', 'Errado. Este é um ponto conceitual importante: é preciso distinguir energia mecânica de energia total.\nEnergia mecânica = cinética + potencial. Ela só se conserva quando atuam apenas forças conservativas (peso, força elástica).\nO atrito é uma força dissipativa: transforma parte da energia mecânica em energia térmica (calor) e sonora. Logo, a energia mecânica diminui.\nA energia TOTAL do universo (incluindo o calor) continua conservada. É o princípio geral da conservação da energia. O item erra ao dizer que a mecânica se conserva.'),
    q(T7, 'Energia e trabalho', 'C', 'Uma mola de constante elástica 800 N/m, comprimida em 0,5 m, lança horizontalmente um bloco de 2 kg sobre superfície sem atrito. O bloco deixa a mola a 10 m/s.', 'Correto. A energia potencial elástica da mola comprimida vira energia cinética do bloco.\n1) Ep elástica = k·x²/2 = 800 · 0,5² / 2 = 800 · 0,25 / 2 = 100 J.\n2) Ec = m·v²/2 ⇒ 100 = 2 · v² / 2 = v² ⇒ v = 10 m/s.\nA superfície sem atrito garante que não há perdas: toda a energia armazenada na mola é transferida ao bloco.'),
    q(T7, 'Energia e trabalho', 'E', 'Um corpo de 2 kg é abandonado de 10 m de altura e chega ao solo a 12 m/s. Com g = 10 m/s², a energia mecânica dissipada pela resistência do ar foi de 20 J.', 'Errado. A energia dissipada é a diferença entre a energia mecânica inicial e a final.\n1) No topo (repouso): Em_i = m·g·h = 2 · 10 · 10 = 200 J.\n2) No solo: Em_f = m·v²/2 = 2 · 12² / 2 = 144 J.\n3) Dissipada: 200 − 144 = 56 J, e não 20 J.\nVerificação de coerência: sem ar, o corpo chegaria a √(2·10·10) ≈ 14,1 m/s. Como chegou a 12 m/s, de fato houve perda.'),
    q(T7, 'Energia e trabalho', 'C', 'Um veículo desce em ponto morto, sem atrito, uma ladeira com desnível de 15 m, partindo do topo a 10 m/s. Com g = 10 m/s², chega ao pé da ladeira a 20 m/s.', 'Correto. Sem atrito, a energia mecânica se conserva. O veículo já tem energia cinética no topo e ainda ganha a energia potencial do desnível.\nm·v₀²/2 + m·g·h = m·v²/2 ⇒ v² = v₀² + 2·g·h.\nResolução: v² = 10² + 2 · 10 · 15 = 100 + 300 = 400 ⇒ v = 20 m/s.\nAtenção à armadilha: não se somam velocidades. O ganho de 15 m de desnível sozinho daria √300 ≈ 17,3 m/s, mas 10 + 17,3 ≠ 20. O que se soma é energia, ou seja, v².'),
    q(T7, 'Energia e trabalho', 'E', 'Um corpo de 2 kg está a 5 m de altura, movendo-se a 10 m/s. Com g = 10 m/s² e referência no solo, sua energia mecânica é de 150 J.', 'Errado. A energia mecânica é a soma da potencial com a cinética: Em = Ep + Ec.\nEp = m·g·h = 2 · 10 · 5 = 100 J.\nEc = m·v²/2 = 2 · 10² / 2 = 100 J.\nEm = 100 + 100 = 200 J. O item diz 150 J.\nDica de prova: calcule cada parcela separadamente e só depois some. Fica mais fácil achar o erro do item.'),
    q(T8, 'Momento e colisões', 'C', 'Um veículo de 1.500 kg a 20 m/s tem quantidade de movimento de módulo 30.000 kg·m/s.', 'Correto. A quantidade de movimento (ou momento linear) é o produto da massa pela velocidade: Q = m·v.\nResolução: Q = 1.500 · 20 = 30.000 kg·m/s.\nLembre-se de que Q é vetorial: tem a mesma direção e o mesmo sentido da velocidade. A unidade kg·m/s é equivalente a N·s (a unidade de impulso).'),
    q(T8, 'Momento e colisões', 'E', 'Um carro de 1.000 kg a 20 m/s colide com um obstáculo e para em 0,1 s. A força média sobre o carro tem módulo de 20 kN.', 'Errado. Pelo teorema do impulso, o impulso da força média é igual à variação da quantidade de movimento: F·Δt = ΔQ.\n1) ΔQ = m·(v_final − v_inicial) = 1.000 · (0 − 20) = −20.000 kg·m/s (módulo 20.000).\n2) F = ΔQ / Δt = 20.000 / 0,1 = 200.000 N = 200 kN.\nO item diz 20 kN, dez vezes menos. Para ter ideia, 200 kN equivalem a 20 vezes o peso do próprio carro. Por isso colisões rígidas são tão destrutivas.'),
    q(T8, 'Momento e colisões', 'C', 'O airbag reduz a força média sobre o ocupante em uma colisão porque aumenta o intervalo de tempo da variação da quantidade de movimento, que é a mesma com ou sem o dispositivo.', 'Correto. Este é um clássico de Física aplicada ao trânsito.\nPelo teorema do impulso: F_média = ΔQ / Δt. Numa colisão, o ocupante sai de uma velocidade v e chega a zero; a variação ΔQ = m·v é a mesma com ou sem airbag.\nO airbag (e também o cinto, que estica um pouco, e as zonas de deformação programada da carroceria) AUMENTA o tempo de parada Δt. Com o mesmo ΔQ e um Δt maior, a força média sobre o corpo diminui.\nÉ o mesmo motivo pelo qual flexionamos os joelhos ao saltar: amortecer é prolongar o tempo da frenagem.'),
    q(T8, 'Momento e colisões', 'E', 'A quantidade de movimento é uma grandeza escalar, definida pelo produto da massa pelo módulo da velocidade.', 'Errado. Quantidade de movimento é grandeza VETORIAL: Q = m·v (vetor Q tem a mesma orientação do vetor v). Tem módulo (m·|v|), direção e sentido, que são os mesmos da velocidade.\nIsso é fundamental em colisões: dois carros de mesma massa e mesma rapidez vindo em sentidos opostos têm quantidade de movimento total ZERO, porque os vetores se cancelam.\nDica de prova: grandezas escalares bem conhecidas são massa, tempo, energia, trabalho e potência. Vetoriais: velocidade, aceleração, força, impulso e quantidade de movimento.'),
    q(T8, 'Momento e colisões', 'C', 'Uma força constante de 500 N aplicada durante 4 s produz impulso de 2.000 N·s.', 'Correto. Impulso de uma força constante é o produto da força pelo intervalo de tempo: I = F·Δt.\nResolução: I = 500 · 4 = 2.000 N·s.\nO impulso também é vetorial, com a mesma direção e sentido da força. Pelo teorema do impulso, esses 2.000 N·s correspondem à variação da quantidade de movimento do corpo.'),
    q(T8, 'Momento e colisões', 'E', 'Duas pessoas de 60 kg e 40 kg, inicialmente em repouso sobre patins em superfície sem atrito, empurram-se mutuamente. Se a de 60 kg sai a 2 m/s, a de 40 kg sai também a 2 m/s, em sentido oposto.', 'Errado. O sistema (as duas pessoas) está isolado de forças externas horizontais, pois não há atrito. Logo, a quantidade de movimento total se conserva.\nAntes: ambas em repouso ⇒ Q_total = 0.\nDepois: 60 · 2 + 40 · v = 0, com v negativo (sentido oposto) ⇒ 40·|v| = 120 ⇒ |v| = 3 m/s.\nA pessoa mais leve sai mais rápida. Massa e velocidade são inversamente proporcionais nessa "explosão" (60/40 = 3/2). O item erra ao supor velocidades iguais.'),
    q(T8, 'Momento e colisões', 'C', 'Uma arma de 4 kg dispara um projétil de 0,02 kg a 400 m/s. A velocidade de recuo da arma é de 2 m/s.', 'Correto. É o mesmo princípio do item anterior: antes do disparo, arma e projétil estão em repouso (Q = 0). Depois, as quantidades de movimento precisam se cancelar.\nm_projétil · v_projétil = m_arma · v_recuo ⇒ 0,02 · 400 = 4 · v.\nResolução: 8 = 4·v ⇒ v = 2 m/s, em sentido oposto ao do projétil.\nÉ por isso que armas mais pesadas "coiceiam" menos: a mesma quantidade de movimento é dividida por uma massa maior.'),
    q(T8, 'Momento e colisões', 'E', 'Uma bola de 0,5 kg atinge perpendicularmente uma parede a 10 m/s e retorna a 10 m/s. Como os módulos das velocidades são iguais, a variação da quantidade de movimento é nula.', 'Errado. A quantidade de movimento é vetorial, então o SENTIDO importa.\nAdotando como positivo o sentido de ida: Q_inicial = 0,5 · (+10) = +5 kg·m/s; Q_final = 0,5 · (−10) = −5 kg·m/s.\nΔQ = Q_final − Q_inicial = −5 − (+5) = −10 kg·m/s, de módulo 10 kg·m/s.\nA variação não é nula; é o dobro do momento inicial. Uma bola que ricocheteia recebe da parede um impulso maior do que uma que apenas para (como uma bola de massinha que gruda). A energia cinética, essa sim, ficou igual.'),
    q(T8, 'Momento e colisões', 'C', 'Em uma colisão, a força sobre um corpo cresce linearmente de 0 a 1.000 N e volta linearmente a zero, em um intervalo total de 0,2 s. O impulso recebido é de 100 N·s.', 'Correto. Quando a força varia com o tempo, o impulso é a ÁREA sob o gráfico F × t.\nO gráfico descrito é um triângulo: base 0,2 s e altura 1.000 N.\nResolução: I = base × altura / 2 = 0,2 · 1.000 / 2 = 100 N·s.\nInterpretação: a força média equivalente seria 100 / 0,2 = 500 N, metade do pico, o que é coerente com um triângulo.'),
    q(T8, 'Momento e colisões', 'E', 'De dois corpos com quantidades de movimento de mesmo módulo, o de menor massa tem menor energia cinética.', 'Errado. É preciso relacionar a energia cinética com a quantidade de movimento.\nComo Q = m·v, temos v = Q/m. Substituindo em Ec = m·v²/2: Ec = m·(Q/m)²/2 = Q²/(2m).\nCom Q fixo, Ec é inversamente proporcional à massa. O corpo de MENOR massa tem MAIOR energia cinética.\nExemplo: um projétil de 0,02 kg e uma arma de 4 kg têm o mesmo |Q| após o disparo, mas a energia cinética do projétil é 200 vezes maior. Por isso o projétil é letal, e o recuo não.'),
    q(T9, 'Momento e colisões', 'C', 'Um carro de 1.000 kg a 20 m/s colide com outro de 1.000 kg parado, e os dois seguem juntos. Imediatamente após a colisão, o conjunto se move a 10 m/s.', 'Correto. Em qualquer colisão de sistema isolado, a quantidade de movimento total se conserva. Como os carros seguem juntos, a colisão é perfeitamente inelástica.\nAntes: Q = 1.000 · 20 + 1.000 · 0 = 20.000 kg·m/s.\nDepois: (1.000 + 1.000) · v = 20.000 ⇒ v = 10 m/s.\nCom massas iguais e um corpo parado, a velocidade final do conjunto é metade da velocidade inicial do corpo em movimento.'),
    q(T9, 'Momento e colisões', 'E', 'Um carro de 1.000 kg a 20 m/s colide com outro de 1.000 kg parado, e os dois seguem juntos. Nessa colisão, não há perda de energia cinética.', 'Errado. A quantidade de movimento se conserva, mas a energia cinética não, porque a colisão é perfeitamente inelástica.\nAntes: Ec = ½ · 1.000 · 20² = 200.000 J = 200 kJ.\nDepois (conjunto a 10 m/s, conforme o item anterior): Ec = ½ · 2.000 · 10² = 100.000 J = 100 kJ.\nPerdeu-se 100 kJ, metade da energia cinética. Ela foi convertida em deformação das latarias, calor e som.\nRegra geral: a colisão perfeitamente inelástica (corpos grudados) é a que mais dissipa energia cinética.'),
    q(T9, 'Momento e colisões', 'C', 'Em uma colisão unidimensional perfeitamente elástica entre dois corpos de mesma massa, estando um deles inicialmente em repouso, os corpos trocam de velocidade.', 'Correto. Em uma colisão perfeitamente elástica, conservam-se a quantidade de movimento e a energia cinética.\nCom massas iguais m e o corpo 2 inicialmente parado:\nQ: m·v₁ = m·v₁\' + m·v₂\' ⇒ v₁ = v₁\' + v₂\'.\nRestituição e = 1: v₂\' − v₁\' = v₁.\nResolvendo o sistema: v₁\' = 0 e v₂\' = v₁. O primeiro para e o segundo sai com a velocidade que o primeiro tinha. Os corpos "trocam de velocidade".\nÉ o que se vê no pêndulo de Newton e numa tacada de sinuca bem central.'),
    q(T9, 'Momento e colisões', 'E', 'Em uma colisão perfeitamente inelástica, o coeficiente de restituição é igual a 1.', 'Errado. O coeficiente de restituição mede quanto da velocidade relativa é "devolvida" após o choque: e = v_afastamento / v_aproximação.\nEscala:\n• e = 1 → colisão perfeitamente elástica (conserva a energia cinética).\n• 0 < e < 1 → colisão parcialmente elástica.\n• e = 0 → colisão perfeitamente inelástica (os corpos seguem juntos; não há afastamento).\nO item inverteu os conceitos: na perfeitamente inelástica, e = 0.'),
    q(T9, 'Momento e colisões', 'C', 'Um caminhão de 4.000 kg a 10 m/s atinge um carro de 1.000 kg parado, e os dois seguem juntos. A velocidade do conjunto logo após o choque é de 8 m/s.', 'Correto. Conservação da quantidade de movimento em colisão perfeitamente inelástica (os dois seguem juntos).\nAntes: Q = 4.000 · 10 + 1.000 · 0 = 40.000 kg·m/s.\nDepois: (4.000 + 1.000) · v = 40.000 ⇒ v = 40.000 / 5.000 = 8 m/s.\nRepare: como o caminhão tem massa muito maior, ele perde pouca velocidade (de 10 para 8 m/s), enquanto o carro vai de 0 a 8 m/s. Para os ocupantes, isso significa uma variação brusca de velocidade, muito mais perigosa no veículo leve.'),
    q(T9, 'Momento e colisões', 'E', 'Um carro A, de 1.200 kg, a 15 m/s para leste, colide frontalmente com um carro B, de 800 kg, a 15 m/s para oeste, e os dois seguem juntos. O conjunto move-se a 3 m/s para oeste.', 'Errado. Como a quantidade de movimento é vetorial, é preciso adotar um sentido positivo. Leste (+) e oeste (−).\nAntes: Q = 1.200 · (+15) + 800 · (−15) = 18.000 − 12.000 = +6.000 kg·m/s (para leste).\nDepois: 2.000 · v = 6.000 ⇒ v = +3 m/s.\nO módulo de 3 m/s está certo, mas o sinal positivo indica LESTE, o sentido do carro de maior massa (que tinha maior quantidade de movimento). O item erra no sentido ao afirmar oeste.\nDica de prova: o Cebraspe adora itens com o valor numérico certo e o detalhe (sentido, unidade ou sinal) errado. Leia até o fim.'),
    q(T9, 'Momento e colisões', 'C', 'Em uma colisão unidimensional, a velocidade relativa de aproximação é de 10 m/s e a de afastamento, 6 m/s. O coeficiente de restituição é 0,6.', 'Correto. O coeficiente de restituição é a razão entre a velocidade relativa de afastamento (depois) e a de aproximação (antes): e = v_af / v_ap.\nResolução: e = 6 / 10 = 0,6.\nComo 0 < e < 1, a colisão é parcialmente elástica: houve perda de energia cinética, mas os corpos se separaram após o choque.'),
    q(T9, 'Momento e colisões', 'E', 'A quantidade de movimento total de um sistema isolado só se conserva em colisões perfeitamente elásticas.', 'Errado. Em um sistema isolado (força externa resultante nula, ou desprezível durante o choque), a quantidade de movimento total se conserva em QUALQUER tipo de colisão: elástica, parcialmente elástica ou perfeitamente inelástica.\nO que só se conserva na colisão perfeitamente elástica é a ENERGIA CINÉTICA.\nResumo para a prova:\n• Q total: conserva-se sempre (sistema isolado).\n• Ec total: conserva-se só na elástica; nas demais, parte vira calor, som e deformação.'),
    q(T9, 'Momento e colisões', 'C', 'Uma bola é abandonada de 5 m de altura e, após quicar no chão, sobe até 1,8 m. Desprezando-se a resistência do ar e com g = 10 m/s², o coeficiente de restituição do choque é 0,6.', 'Correto. Aqui combinamos conservação de energia e coeficiente de restituição.\n1) Velocidade ao chegar ao chão (queda de 5 m): v = √(2·g·h) = √(2 · 10 · 5) = √100 = 10 m/s.\n2) Velocidade ao sair do chão (para subir até 1,8 m): v\' = √(2 · 10 · 1,8) = √36 = 6 m/s.\n3) O chão está parado, então e = v\' / v = 6 / 10 = 0,6.\nAtalho útil: e = √(h_final / h_inicial) = √(1,8/5) = √0,36 = 0,6.'),
    q(T9, 'Momento e colisões', 'E', 'Um corpo de 2 kg a 6 m/s colide com outro de 1 kg em repouso, e eles seguem juntos. A energia cinética dissipada no choque é de 24 J.', 'Errado. O item confunde a energia que sobrou com a energia que foi perdida.\n1) Conservação de Q: 2 · 6 + 1 · 0 = (2 + 1) · v ⇒ 12 = 3v ⇒ v = 4 m/s.\n2) Ec antes: ½ · 2 · 6² = 36 J.\n3) Ec depois: ½ · 3 · 4² = 24 J.\n4) Energia dissipada: 36 − 24 = 12 J.\nOs 24 J são a energia cinética RESTANTE após o choque, e não a dissipada.\nDica de prova: leia com atenção o que o item pergunta. "Dissipada", "restante" e "final" são palavras-chave que mudam completamente a resposta.')
  ]);
})();
